    host.innerHTML =
      '<div class="crist-anim__view">' +
      '<img class="crist-anim__img crist-anim__base" alt="Cristalizador: el jarabe entra por la izquierda, cristaliza al evaporarse al vacío, el vapor sale por arriba y la masa cocida descarga por abajo" draggable="false">' +
      '<canvas class="crist-anim__canvas crist-anim__tint" aria-hidden="true"></canvas>' +
      '<canvas class="crist-anim__canvas crist-anim__cl" aria-hidden="true"></canvas>' +
      '<img class="crist-anim__img crist-anim__front" alt="" aria-hidden="true" draggable="false">' +
      '<canvas class="crist-anim__canvas crist-anim__ci" aria-hidden="true"></canvas>' +
      '<canvas class="crist-anim__canvas crist-anim__cv" aria-hidden="true"></canvas>' +
      '<canvas class="crist-anim__canvas crist-anim__cs" aria-hidden="true"></canvas>' +
      '<button type="button" class="crist-anim__btn"></button></div>';
    var q = function (c) { return host.querySelector('.crist-anim__' + c); };
    var view = q('view'), btn = q('btn');
    q('base').src = imgs.base; q('front').src = imgs.front;
    var tn = q('tint'), cl = q('cl'), ci = q('ci'), cvv = q('cv'), cs = q('cs');
    var xt = tn.getContext('2d'), xl = cl.getContext('2d'), xi = ci.getContext('2d'), xv = cvv.getContext('2d'), xs = cs.getContext('2d');
    // lienzos auxiliares para recortar con máscara
    var sI = cv(1, 1), sV = cv(1, 1), sS = cv(1, 1), xsI = sI.getContext('2d'), xsV = sV.getContext('2d'), xsS = sS.getContext('2d');
    var mI = cv(1, 1), mV = cv(1, 1), mS = cv(1, 1), mRaw = {};
