      x.beginPath(); for (i = 0; i < n; i++) { x.moveTo(h, h); x.lineTo(h + (pts[i][0] - h) * 0.94, h + (pts[i][1] - h) * 0.94); } x.strokeStyle = 'rgba(255,244,208,.40)'; x.stroke();
      x.strokeStyle = 'rgba(255,240,196,.85)'; x.lineWidth = Math.max(1, size * 0.02); poly(0.94); x.stroke();
